def transform(g):
    import numpy as np
    a=np.array(g); H,W=a.shape
    dr=[r for r in range(H) if len(set(a[r]))==1]
    dc=[c for c in range(W) if len(set(a[:,c]))==1]
    r0=dr[0]; c0=dc[0]
    bg=a[0,0]
    quads={'TL':(slice(0,r0),slice(0,c0)),'TR':(slice(0,r0),slice(c0+1,W)),'BL':(slice(r0+1,H),slice(0,c0)),'BR':(slice(r0+1,H),slice(c0+1,W))}
    nz={q:int((a[s]!=bg).sum()) for q,s in quads.items()}
    pq=max(nz,key=nz.get)
    P=a[quads[pq]].copy()
    res=a.copy()
    for q,s in quads.items():
        if q==pq: continue
        h,w=a[s].shape
        res[s]=P[:h,:w]
    return res.tolist()
