def segments(divs, n):
    seg=[]; start=0
    for r in divs:
        if r>start: seg.append((start,r))
        start=r+1
    if start<n: seg.append((start,n))
    return seg
def transform(g):
    import numpy as np
    a=np.array(g); H,W=a.shape
    dr=[r for r in range(H) if len(set(a[r]))==1]
    dc=[c for c in range(W) if len(set(a[:,c]))==1]
    rseg=segments(dr,H); cseg=segments(dc,W)
    bg=a[0,0]
    regions=[(slice(r1,r2),slice(c1,c2)) for r1,r2 in rseg for c1,c2 in cseg]
    nz={i:int((a[s]!=bg).sum()) for i,s in enumerate(regions)}
    pi=max(nz,key=nz.get)
    P=a[regions[pi]]
    rows=np.where((P!=bg).any(1))[0]; cols=np.where((P!=bg).any(0))[0]
    B=P[rows.min():rows.max()+1, cols.min():cols.max()+1]
    res=a.copy()
    for i,s in enumerate(regions):
        if i==pi: continue
        h,w=a[s].shape
        res[s]=bg
        m=min(h,B.shape[0]); n=min(w,B.shape[1])
        res[s][:m,:n]=B[:m,:n]
    return res.tolist()
